WITH items AS (SELECT value AS j FROM jsonb_array_elements($DATA$[{"order":1,"title":"القواعد: مراجعة عامة لما سبقت دراسته","content":"القواعد: مراجعة عامة لما سبقت دراسته\n\nأهداف تعلم قابلة للقياس\n• يميّز أنواع الجملة وأركانها في خمسة أمثلة.\n• يعرب فاعلًا ومفعولًا به وخبرًا وفق مواضعها.\n• يصوّب أخطاء في جمل وظيفية قصيرة.\n\nأفهم الدرس\nنجمع في هذه المراجعة بعض القواعد السابقة من غير أن نعامل الدروس كلها قاعدة واحدة. في «قرأَ العاملُ التنبيهَ» الفاعل العاملُ مرفوع والمفعول التنبيهَ منصوب. وفي «الموعدُ قريبٌ» مبتدأ وخبر مرفوعان. وإذا أدخلنا «كان» قلنا «كان الموعدُ قريبًا»، أما مع «إنَّ» فنقول «إنَّ الموعدَ قريبٌ». ننتبه أيضًا إلى بناء الفعل الماضي وعلامات رفع المثنى والجمع. تفسير الحركة يبدأ بمعرفة وظيفة الكلمة في الجملة، لا بحفظ شكلها منفردًا.\n\nأمثلة وتفسير\n«حضر الموظفانِ» فاعل مثنى مرفوع بالألف. «شكر المديرُ المتطوعينَ» مفعول به جمع مذكر سالم منصوب بالياء. الكلمات نفسها قد تختلف علاماتها عند انتقالها بين الوظائف.\n\nتدريبات تطبيقية\nحدّد الفاعل والمفعول في «سلّم خالدٌ الملفَّ». صحح «كان النشاطَ مفيدٌ». كوّن جملة تبدأ بـ«إنَّ» وبيّن اسمها وخبرها.\n\nمفتاح الإجابة والتغذية الراجعة\nخالدٌ فاعل، الملفَّ مفعول؛ «كان النشاطُ مفيدًا»؛ مثال «إنَّ التعاونَ نافعٌ». يُراجع إعراب كل كلمة قبل التصحيح.\n\nتطبيق في حياتي اليومية\nاقرأ رسالة عمل ثم اختر منها جملة فعلية وأخرى اسمية، وعدّل جملة ثالثة باستخدام كان أو إن دون تغيير مقصد الكاتب.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميّز أنواع الجملة وأركانها في خمسة أمثلة.","يعرب فاعلًا ومفعولًا به وخبرًا وفق مواضعها.","يصوّب أخطاء في جمل وظيفية قصيرة."],"vocabulary":[{"word":"وظيفة إعرابية","meaning":"موقع الكلمة وعملها في تركيب الجملة"},{"word":"علامة فرعية","meaning":"علامة تقوم مقام الحركة الأصلية"}],"quiz":{"prompt":"ما التصحيح المناسب لـ«كان الاجتماعَ مفيدٌ»؟","options":["كان الاجتماعُ مفيدًا","كان الاجتماعَ مفيدًا","كان الاجتماعُ مفيدٌ","إن الاجتماعُ مفيدًا"],"correct":"كان الاجتماعُ مفيدًا"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":2,"title":"القراءة: أنت الهوى - دراسة القصيدة كاملة، والحفظ من 1 إلى 7","content":"القراءة: أنت الهوى - دراسة القصيدة كاملة، والحفظ من 1 إلى 7\n\nأهداف تعلم قابلة للقياس\n• يستخلص معنى المحبة المسؤولة من نص نثري مستقل.\n• يفصل بين المجاز اللغوي والوصف المباشر.\n• يعرف أن حفظ أبيات القصيدة المقررة ينتظر مطابقة مصدرها.\n\nأفهم الدرس\nالعنوان في الخطة «أنت الهوى» مع دراسة القصيدة وحفظ الأبيات 1–7. لا يتوافر لنا في هذا العمل نص الأبيات المثبت من الكتاب، لذلك لا نضع أي أبيات منسوبة للشاعر. نقدم نصًا أصليًا مختلفًا: «يتذكر سالم المواقف التي ساعده فيها أهله وجيرانه. كلما زار حيه القديم رأى المدرسة والساحة، فشعر بالمودة والامتنان. لم يكتف بالحنين، بل ساهم في إصلاح مكتبة صغيرة ليستفيد منها الأطفال والكبار». الحب هنا ليس مجرد إحساس بل سلوك نافع. كلمة «الهوى» في السياق الأدبي قد تدل على الميل والمحبة، ويحدّد معناها الدقيق نصها وسياقها.\n\nأمثلة وتفسير\nالوصف المباشر: شارك في إصلاح المكتبة. الشعور: المودة والامتنان. الاستنتاج: يمكن أن تتحول المحبة إلى خدمة الآخرين دون المبالغة في وصف أعمال لم تحدث.\n\nتدريبات تطبيقية\nاذكر مكانين أثارا ذكريات سالم. استخرج فعلًا يدل على المحبة العملية. اكتب ثلاثة أسطر عن شعور تجاه مكان تحبه دون نسبة كتابتك إلى القصيدة المقررة.\n\nمفتاح الإجابة والتغذية الراجعة\nالمدرسة والساحة؛ ساهم في إصلاح مكتبة؛ تقبل فقرة تميز الشعور والفعل وتراعي الصدق.\n\nتطبيق في حياتي اليومية\nاكتب عملًا بسيطًا يمكنك تقديمه لأسرتك أو مجتمعك تعبيرًا عن التقدير، ثم حدّد كيف تتحقق من أثره.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يستخلص معنى المحبة المسؤولة من نص نثري مستقل.","يفصل بين المجاز اللغوي والوصف المباشر.","يعرف أن حفظ أبيات القصيدة المقررة ينتظر مطابقة مصدرها."],"vocabulary":[{"word":"الهوى","meaning":"الميل أو المحبة بحسب السياق"},{"word":"امتنان","meaning":"شعور بالشكر تجاه المعروف"}],"quiz":{"prompt":"كيف عبّر سالم عن المودة عمليًا؟","options":["ساهم في إصلاح مكتبة","اكتفى بالحنين فقط","تجاهل جيرانه","أغلق المدرسة"],"correct":"ساهم في إصلاح مكتبة"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":3,"title":"القواعد: المقصور والمنقوص والممدود (تثنيتها وجمعها جمعًا سالمًا)","content":"القواعد: المقصور والمنقوص والممدود (تثنيتها وجمعها جمعًا سالمًا)\n\nأهداف تعلم قابلة للقياس\n• يميز بنية الاسم المقصور والمنقوص والممدود.\n• يستنتج التغيير الإملائي عند التثنية.\n• يطبق مثالًا صحيحًا لجمع سالم ويشير إلى شروطه.\n\nأفهم الدرس\nالاسم المقصور آخره ألف لازمة «عصا، فتى»، والمنقوص آخره ياء لازمة مكسور ما قبلها «القاضي»، والممدود آخره همزة قبلها ألف زائدة «صحراء، بناء». في التثنية: عصا ← عصوانِ، فتى ← فتيانِ، القاضي ← القاضيانِ، بناء ← بناءانِ في الاستعمال الذي تبقى فيه الهمزة الأصلية، وصحراء ← صحراوانِ لأن الهمزة فيها للتأنيث. ليست جميع الأسماء قابلة للجمع السالم بلا قيود، وتتأثر الصيغ بأصل الألف ونوع الهمزة والمعنى. يراجع الدارس المعجم عند الشك بدل اختراع جمع لكلمة.\n\nأمثلة وتفسير\n«القاضيانِ» مثنى من القاضي. «صحراوانِ» مثنى من صحراء بسبب همزة التأنيث. «فتيانِ» مثنى من فتى بعد رد الألف إلى أصلها اليائي.\n\nتدريبات تطبيقية\nصنّف «فتى، القاضي، صحراء». اكتب مثنى «عصا» و«فتى». بيّن لماذا لا نكتفي بإضافة «ان» مباشرة إلى «صحراء» في المثال.\n\nمفتاح الإجابة والتغذية الراجعة\nفتى مقصور، القاضي منقوص، صحراء ممدود؛ عصوانِ وفتيانِ؛ همزة التأنيث في صحراء تقلب واوًا عند التثنية.\n\nتطبيق في حياتي اليومية\nإذا ورد اسم من هذه الأنواع في مستند رسمي، تحقق من صيغته عند تثنيته باستخدام مرجع لغوي قبل الإرسال.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميز بنية الاسم المقصور والمنقوص والممدود.","يستنتج التغيير الإملائي عند التثنية.","يطبق مثالًا صحيحًا لجمع سالم ويشير إلى شروطه."],"vocabulary":[{"word":"مقصور","meaning":"اسم معرب آخره ألف لازمة"},{"word":"ممدود","meaning":"اسم معرب آخره همزة قبلها ألف زائدة"}],"quiz":{"prompt":"ما المثنى الصحيح لـ«فتى» في حالة الرفع؟","options":["فتيانِ","فتانِ","فتىانِ","فتوينِ"],"correct":"فتيانِ"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":4,"title":"الإنتاج الكتابي: إعداد خطة عمل للموضوع الإنشائي السردي - تحديد الأحداث الرئيسة","content":"الإنتاج الكتابي: إعداد خطة عمل للموضوع الإنشائي السردي - تحديد الأحداث الرئيسة\n\nأهداف تعلم قابلة للقياس\n• ينظم مخططًا سرديًا من خمس نقاط.\n• يفرق بين الحدث المحوري والتفصيل الهامشي.\n• يربط الأحداث بعبارات زمانية مناسبة.\n\nأفهم الدرس\nقبل كتابة قصة نرسم مسار الأحداث دون تكديس الأوصاف. نفترض موقفًا أصليًا: «خرجت مريم لتجديد بطاقة مكتبة. وصلت قبل الموعد، لكنها نسيت نموذج التسجيل. سألت الموظفة عن طريقة الحصول عليه، وملأته ثم أكملت الإجراء». نكتب الخطة: 1) الشخصية والهدف، 2) المكان والزمن، 3) العقبة، 4) محاولة الحل، 5) النتيجة. التفاصيل مثل لون الباب لا تكون حدثًا رئيسًا إلا إذا أثرت في المشكلة. يساعد المخطط على الحفاظ على منطق السبب والنتيجة.\n\nأمثلة وتفسير\nالأحداث الرئيسة: نسيان النموذج ثم الاستفسار ثم إكمال التسجيل. التفاصيل الثانوية: لون حقيبة مريم، ما لم يترتب عليه شيء.\n\nتدريبات تطبيقية\nرتب «أكملت الطلب، نسيت النموذج، سألت الموظفة، وصلت إلى المكتبة». اكتب مخططًا لزيارة مركز صحي دون اختلاق معلومات طبية أو بيانات أشخاص.\n\nمفتاح الإجابة والتغذية الراجعة\nوصلت، نسيت، سألت، أكملت؛ وتقبل خطة فيها غرض واضح وعقبة وحل ونتيجة.\n\nتطبيق في حياتي اليومية\nاستخدم المخطط عند كتابة تجربة تعلم شخصية، ثم راجع التسلسل مع أحد الزملاء.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["ينظم مخططًا سرديًا من خمس نقاط.","يفرق بين الحدث المحوري والتفصيل الهامشي.","يربط الأحداث بعبارات زمانية مناسبة."],"vocabulary":[{"word":"عقدة","meaning":"حدث يخلق مشكلة تحتاج حلًا"},{"word":"خطة سرد","meaning":"قائمة مرتبة للأحداث قبل الكتابة"}],"quiz":{"prompt":"ما الحدث الذي يمثل العقدة في المثال؟","options":["نسيان نموذج التسجيل","إكمال الطلب","مغادرة المكتبة","كتابة الخاتمة"],"correct":"نسيان نموذج التسجيل"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":5,"title":"القراءة: إلى ولدي","content":"القراءة: إلى ولدي\n\nأهداف تعلم قابلة للقياس\n• يستخلص معنى النصيحة الداعمة من نص أصلي.\n• يميز النصيحة عن الأمر الجارح.\n• يكتب رسالة قصيرة تشجع على التعلم المستمر.\n\nأفهم الدرس\nعنوان الكتاب «إلى ولدي» ولم يُطابق متنه الرسمي في هذا التدقيق. النص التالي أصلي من ضاديوم: «كتب أب لابنه الذي بدأ وظيفة جديدة: يا بني، تعلم من زملائك ولا تخجل من السؤال. إذا أخطأت في عملك فأخبر المسؤول وصحح الخطأ. احفظ وقتك وراع حقوق الآخرين، وتذكّر أن الخبرة تنمو بالممارسة. رد الابن بأنه سيخصص وقتًا أسبوعيًا لتطوير مهاراته». نتعلم أن النصيحة تدعم المسؤولية وتبتعد عن التهديد. وفي أدب الرسائل، تحدد العلاقة بين المرسل والمتلقي درجة القرب واللغة.\n\nأمثلة وتفسير\nعبارة «لا تخجل من السؤال» تشجيع، و«صحح الخطأ» توجيه عملي. لا يستلزم احترام الكبير قبول كل رأي دون تمحيص.\n\nتدريبات تطبيقية\nما ثلاث نصائح في الرسالة؟ كيف يختلف تشجيع الابن عن لومه؟ اكتب أربع جمل إلى متعلم جديد تتضمن تحية وخطوة تعلم محددة.\n\nمفتاح الإجابة والتغذية الراجعة\nطلب التعلم والسؤال وتصحيح الأخطاء واحترام الوقت؛ تقبل رسالة مهذبة ذات مضمون قابل للتطبيق.\n\nتطبيق في حياتي اليومية\nأرسل رسالة دعم إلى شخص يستعد لتعلم مهارة، مستأذنًا قبل مشاركة معلوماته مع غيره.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يستخلص معنى النصيحة الداعمة من نص أصلي.","يميز النصيحة عن الأمر الجارح.","يكتب رسالة قصيرة تشجع على التعلم المستمر."],"vocabulary":[{"word":"نصيحة","meaning":"توجيه يقصد به النفع"},{"word":"ممارسة","meaning":"تكرار منظم لتحسين مهارة"}],"quiz":{"prompt":"ما النصيحة التي تساعد على التعلم في النص؟","options":["لا تخجل من السؤال","أخف الخطأ دائمًا","توقف عن المحاولة","ارفض مساعدة الآخرين"],"correct":"لا تخجل من السؤال"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":6,"title":"القواعد: أسلوب الاستثناء - المستثنى بـ(إلا)","content":"القواعد: أسلوب الاستثناء - المستثنى بـ(إلا)\n\nأهداف تعلم قابلة للقياس\n• يحدد الأداة والمستثنى والمستثنى منه.\n• يعرب المستثنى في التام المثبت.\n• يفرق بين التام المنفي والناقص المنفي.\n\nأفهم الدرس\nفي «حضر المتطوعونَ إلا واحدًا» الأسلوب تام مثبت لأن المستثنى منه «المتطوعون» موجود ولا نفي، و«واحدًا» مستثنى منصوب. وفي «ما حضرَ إلا واحدٌ» الأسلوب ناقص منفي، وتُعرب «واحدٌ» فاعلًا مرفوعًا، لأن الجملة تفرغت لما بعد «إلا». وفي «ما حضر المتطوعون إلا واحدٌ / واحدًا» قد يصح البدل أو النصب في حالات التام المنفي، ولا يصح تعميم حكم واحد على كل السياقات. نحدد وجود النفي والمستثنى منه قبل الإعراب.\n\nأمثلة وتفسير\n«قرأتُ الملفاتَ إلا ملفًا» تام مثبت؛ «ما قرأتُ إلا ملفًا» ناقص منفي والمفعول ملفًا.\n\nتدريبات تطبيقية\nحدد أركان «زارَ الناسُ المعرضَ إلا زائرًا واحدًا» من جهة أداة الاستثناء والمستثنى منه الصحيح في السياق، ثم أعرب «ما جاء إلا سالمٌ». صحح «نجح الطلاب إلا طالبٌ» في الأسلوب التام المثبت.\n\nمفتاح الإجابة والتغذية الراجعة\n«إلا» أداة، لكن جملة «زار الناس المعرض إلا زائرًا» صياغتها متعارضة دلاليًا لأن الزائر من الناس وقد لا يكون من زاره؛ الأفضل «زارَ الطلابُ المعرضَ إلا طالبًا». «سالمٌ» فاعل مرفوع، و«طالبًا» مستثنى منصوب.\n\nتطبيق في حياتي اليومية\nاكتب عن حضور فريق دون ذكر اسم المتغيب الحقيقي إذا لم تكن هناك حاجة.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يحدد الأداة والمستثنى والمستثنى منه.","يعرب المستثنى في التام المثبت.","يفرق بين التام المنفي والناقص المنفي."],"vocabulary":[{"word":"تام","meaning":"أسلوب ذُكر فيه المستثنى منه"},{"word":"مفرّغ","meaning":"استثناء ناقص منفي يعرب ما بعد إلا حسب موقعه"}],"quiz":{"prompt":"ما إعراب «خالدٌ» في «ما جاء إلا خالدٌ»؟","options":["فاعل مرفوع","مستثنى منصوب وجوبًا","مفعول به","خبر كان"],"correct":"فاعل مرفوع"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":7,"title":"القراءة: كن بلسمًا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6","content":"القراءة: كن بلسمًا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6\n\nأهداف تعلم قابلة للقياس\n• يتعرف قيمة التخفيف عن الآخرين في نثر داعم.\n• يستخرج فعلين للتعامل بلطف مع الناس.\n• يميز النثر المساند عن قصيدة الكتاب التي تتطلب توثيقًا مستقلًا.\n\nأفهم الدرس\nترد قصيدة «كن بلسمًا» في الخطة مع دراسة كاملة وحفظ الأبيات 1–6، ولا نعرض أبياتًا لم تُطابق من مصدر الكتاب. نص ضاديوم البديل مستقل: «عاد حسن من عمله ورأى جارًا مسنًا يبحث عن عنوان غرفة في المركز. عرض حسن أن يقرأ له اللوحة، ثم اصطحبه إلى مكتب الاستقبال. شكر الجار مساعدته وقال إنها وفرت عليه وقتًا». نقف عند قيمة الرحمة العملية، ونلاحظ أن المساعدة النافعة تستأذن صاحبها وتراعي سلامته وكرامته، ولا تحوله إلى شخص عاجز في وصفنا.\n\nأمثلة وتفسير\nالمساعدة هنا قراءة اللافتة والإرشاد لا إعطاء وعود لا قدرة على تنفيذها. كلمة «بلسم» في المجاز تشير إلى ما يخفف الألم أو المعاناة.\n\nتدريبات تطبيقية\nما المشكلة التي واجهها الجار؟ كيف ساعده حسن؟ اكتب موقفًا تتعامل فيه بلطف من دون كشف اسم حقيقي، ولا تحفظ الفقرة على أنها القصيدة.\n\nمفتاح الإجابة والتغذية الراجعة\nلم يجد المكان؛ قُرئت له اللوحة وأرشد للمكتب؛ تقبل فقرة قصيرة تظهر أثر السلوك.\n\nتطبيق في حياتي اليومية\nعند مساعدة متعلم آخر، اسأله أولًا عما يحتاجه ثم اعطه فرصة للمحاولة.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يتعرف قيمة التخفيف عن الآخرين في نثر داعم.","يستخرج فعلين للتعامل بلطف مع الناس.","يميز النثر المساند عن قصيدة الكتاب التي تتطلب توثيقًا مستقلًا."],"vocabulary":[{"word":"بلسم","meaning":"مادة أو صورة مجازية لما يخفف المعاناة"},{"word":"رحمة","meaning":"رفق يقود إلى فعل نافع"}],"quiz":{"prompt":"ما الفعل الذي جسّد الرحمة في النص الداعم؟","options":["أرشده إلى مكتب الاستقبال","تركه يبحث وحده","سخر منه","أخفى اللوحة"],"correct":"أرشده إلى مكتب الاستقبال"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":8,"title":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (1)","content":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (1)\n\nأهداف تعلم قابلة للقياس\n• يحدد خمسة عناصر أساسية للقصة.\n• يوظف رابطين زمنيين بين الأحداث.\n• ينشئ بداية وعقدة تمهد لحل معقول.\n\nأفهم الدرس\nتبدأ كتابة القصة بتحديد شخصية ومكان وزمن وهدف وعقبة. في نموذج ضاديوم «دخلت سارة مركز التعلم صباحًا لحضور دورة خط. لم تجد القاعة في الطابق المعتاد، فنظرت إلى لوحة المواعيد الجديدة». هذه بداية وعقدة، ولم نكتب الحل بعد حتى يفكر الدارس في خيار مناسب. يجب أن يرتبط الحل بالمشكلة، فلا نظهر شخصية مفاجئة تنهي كل شيء بلا سبب. روابط «أولًا، بعد ذلك، ثم» توضح الزمن لكنها لا تعوض منطق الأحداث.\n\nأمثلة وتفسير\nالشخصية سارة، المكان مركز التعلم، الهدف دورة الخط، المشكلة تغيّر القاعة. الحل المحتمل الاستفسار من مكتب الاستقبال.\n\nتدريبات تطبيقية\nاكتب مخططًا من خمس نقاط لقصة عن فقدان بطاقة دخول ثم العثور على طريقة رسمية بديلة. ضع سؤالًا ينتظر القارئ جوابه في الوسط.\n\nمفتاح الإجابة والتغذية الراجعة\nتقبل خطة تتضمن الشخصيات والزمان والمكان والعقدة ثم خطوة نحو حل مشروع دون اختراق إجراءات المكان.\n\nتطبيق في حياتي اليومية\nقبل كتابة قصة من الواقع، أخف تفاصيل الأشخاص الآخرين أو استأذنهم.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يحدد خمسة عناصر أساسية للقصة.","يوظف رابطين زمنيين بين الأحداث.","ينشئ بداية وعقدة تمهد لحل معقول."],"vocabulary":[{"word":"عناصر القصة","meaning":"الشخصيات والزمان والمكان والأحداث والعقدة والحل"},{"word":"بداية","meaning":"مدخل يعرف القارئ بالموقف"}],"quiz":{"prompt":"ما العقدة في نموذج سارة؟","options":["لم تجد القاعة في مكانها السابق","حضرت صباحًا","كانت متعلمة","دخلت المركز"],"correct":"لم تجد القاعة في مكانها السابق"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":9,"title":"القواعد: أسلوب الاستثناء - المستثنى بغير وسوى وخلا وعدا","content":"القواعد: أسلوب الاستثناء - المستثنى بغير وسوى وخلا وعدا\n\nأهداف تعلم قابلة للقياس\n• يميّز إعراب غير وسوى وإضافة الاسم بعدهما.\n• يقارن بين خلا وعدا في استعمال فعلي أو حرفي.\n• يكتب أمثلة توضح المستثنى منه.\n\nأفهم الدرس\n«غير» و«سوى» اسمان يستعملان للاستثناء، ويأتي الاسم بعدهما مضافًا إليه مجرورًا: «حضر الجميعُ غيرَ خالدٍ»، فكلمة غير مستثنى منصوب في التام المثبت، وخالد مضاف إليه. «سوى» اسم مقصور تُقدر عليه الحركة المناسبة بحسب الموقع: «حضر الجميعُ سوى خالدٍ». أما «خلا» و«عدا» فقد تستعملان فعلين فينصب ما بعدهما أو حرفي جر فيجر، مثل «حضر الجميعُ خلا خالدًا / خالدٍ» بحسب التخريج. إذا سبقت «ما» المصدرية خلا أو عدا تعيّن النصب في القاعدة المدرسية الشائعة مثل «ما عدا خالدًا».\n\nأمثلة وتفسير\nبعد «غير» و«سوى» الاسم مضاف إليه مجرور. بعد «ما عدا» يأتي الاسم منصوبًا في المثال التعليمي.\n\nتدريبات تطبيقية\nحدد حركة «سالم» في «حضر الجميعُ غيرَ سالمٍ». صحح «ما عدا طالبٍ» بحسب القاعدة التعليمية المقصودة، وحدد أداة الاستثناء في «ما خلا زيدًا».\n\nمفتاح الإجابة والتغذية الراجعة\nسالمٍ مضاف إليه؛ «ما عدا طالبًا»؛ خلا جاءت بعد ما المصدرية في المثال، والاسم منصوب.\n\nتطبيق في حياتي اليومية\nعند كتابة ملاحظة عن حضور مجموعة، اختر أسلوبًا واضحًا وتجنب الالتباس بين الاستثناء والتعميم.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميّز إعراب غير وسوى وإضافة الاسم بعدهما.","يقارن بين خلا وعدا في استعمال فعلي أو حرفي.","يكتب أمثلة توضح المستثنى منه."],"vocabulary":[{"word":"غير وسوى","meaning":"اسمان للاستثناء مضافان إلى ما بعدهما"},{"word":"خلا وعدا","meaning":"لفظان قد يعربان فعلين أو حرفي جر"}],"quiz":{"prompt":"ما إعراب «عليٍّ» في «حضروا غيرَ عليٍّ»؟","options":["مضاف إليه مجرور","فاعل مرفوع","خبر إن","حال منصوب"],"correct":"مضاف إليه مجرور"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":10,"title":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (2)","content":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (2)\n\nأهداف تعلم قابلة للقياس\n• ينجز حلًا منطقيًا لعقدة قصة سبق التخطيط لها.\n• يربط النتيجة بفعل الشخصية.\n• يراجع القصة كاملة بحثًا عن قفزات زمنية.\n\nأفهم الدرس\nنكمل قصة سارة من الدرس السابق من دون بدء موضوع جديد: «سألت سارة موظفة الاستقبال عن مكان دورة الخط، فأشارت الموظفة إلى إشعار بنقل القاعة. قرأت سارة الرقم الجديد وصعدت إلى الطابق المحدد، ثم وصلت قبل بدء التدريب. سجّلت الرقم في دفترها حتى لا تضيع القاعة في الزيارة المقبلة». جاءت النهاية من حل مرتبط بالمشكلة: سؤال، قراءة الإشعار، الوصول. لا نضيف أحداثًا لا تخدم المعنى، ونسأل بعد المراجعة: هل يعلم القارئ كيف حلّت الشخصية مشكلتها؟\n\nأمثلة وتفسير\nالقصة تبدأ بهدف واضح، وتتقدم بعقبة تغيير القاعة، وتنتهي بخطوات قابلة للفهم. النتيجة ليست حظًا مفاجئًا.\n\nتدريبات تطبيقية\nاكتب نهاية من أربع جمل لقصة فقدان بطاقة الدخول، واجعل الشخصية تتبع الإجراءات الرسمية. راجع ضمائر القصة والوقت والنتيجة.\n\nمفتاح الإجابة والتغذية الراجعة\nتقبل نهاية تُظهر الاستفسار والتحقق واتباع الإجراء ثم الوصول إلى حل دون تجاوز الصلاحيات.\n\nتطبيق في حياتي اليومية\nاستعمل قائمة تحقق عند كتابة قصة للمشاركة أمام زملائك.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["ينجز حلًا منطقيًا لعقدة قصة سبق التخطيط لها.","يربط النتيجة بفعل الشخصية.","يراجع القصة كاملة بحثًا عن قفزات زمنية."],"vocabulary":[{"word":"حل عقدة","meaning":"أحداث تنتهي بها المشكلة"},{"word":"اتساق","meaning":"عدم تناقض أحداث القصة"}],"quiz":{"prompt":"ما الذي جعل نهاية قصة سارة منطقية؟","options":["وجدت إشعار القاعة ثم اتبعته","ظهرت القاعة من دون سبب","تغير الوقت بلا إعلان","لم تسأل أحدًا"],"correct":"وجدت إشعار القاعة ثم اتبعته"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":11,"title":"القراءة: يا شباب العرب","content":"القراءة: يا شباب العرب\n\nأهداف تعلم قابلة للقياس\n• يقرأ فقرة أصلية عن مشاركة الشباب في المجتمع.\n• يفرق بين دعوة عامة وخطوة قابلة للتنفيذ.\n• يقترح تعاونًا يحترم تنوع الخبرات والأعمار.\n\nأفهم الدرس\nالعنوان «يا شباب العرب» في الخطة، لكن هذه الفقرة ليست نص الكتاب. «اجتمع شباب متطوعون مع مجموعة من كبار السن لتنظيم ورشة قراءة رقمية. عرض الشباب طريقة استخدام خدمة عامة عبر الهاتف، وقدم الكبار خبراتهم في التعامل مع الوثائق. تعلّم الجميع أن العطاء لا يرتبط بعمر واحد، وأن نجاح النشاط يتطلب إصغاءً وتبادلًا للأدوار». نلاحظ أن الكلام عن دور الشباب لا ينتقص من قدرة الكبار أو خبراتهم، وأن المهارة تُكتسب بالتعاون.\n\nأمثلة وتفسير\nدعوة عامة: «تعاونوا لخدمة المجتمع». خطوة محددة: «خصصوا ساعة لمساعدة الدارسين على قراءة الإعلانات العامة».\n\nتدريبات تطبيقية\nما الخبرة التي قدمها كبار السن؟ ماذا قدم الشباب؟ اكتب اقتراحًا لنشاط من ثلاث خطوات يشترك فيه أشخاص من جيلين.\n\nمفتاح الإجابة والتغذية الراجعة\nخبرات التعامل مع الوثائق؛ شرح خدمة عبر الهاتف؛ تقبل اقتراحًا يوزع المهام ويحترم المشاركين.\n\nتطبيق في حياتي اليومية\nاقترح نشاطًا تعليميًا صغيرًا يجمع تعلم مهارة رقمية وخبرة عملية من الحياة اليومية.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يقرأ فقرة أصلية عن مشاركة الشباب في المجتمع.","يفرق بين دعوة عامة وخطوة قابلة للتنفيذ.","يقترح تعاونًا يحترم تنوع الخبرات والأعمار."],"vocabulary":[{"word":"تطوع","meaning":"مشاركة نافعة برضا الشخص"},{"word":"تبادل خبرات","meaning":"مشاركة المعرفة بين أشخاص مختلفين"}],"quiz":{"prompt":"ما الذي ساعد على نجاح الورشة في النص؟","options":["تبادل خبرات الشباب والكبار","الاعتماد على عمر واحد","منع الأسئلة","إلغاء التعاون"],"correct":"تبادل خبرات الشباب والكبار"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$DATA$::jsonb)),
target AS (
 SELECT l.id,i.j FROM items i
 JOIN public.lessons l ON l.title=i.j->>'title' AND l.sort_order=(i.j->>'order')::int
 JOIN public.units u ON u.id=l.unit_id AND u.semester=1
 JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الثاني تقوية' AND g.grade_number IS NULL
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.' AND l.learning_objectives='[]'::jsonb AND l.instructions='[]'::jsonb
)
UPDATE public.lessons l SET
 content=t.j->>'content',learning_objectives=t.j->'learning_objectives',vocabulary=t.j->'vocabulary',
 instructions=jsonb_build_array(jsonb_build_object('origin','DADYOOM_BH_REINFORCEMENT2_DRAFT_V1','editorial_review','required','book_text_copied',false)),
 updated_at=now()
FROM target t WHERE l.id=t.id;
WITH items AS (SELECT value AS j FROM jsonb_array_elements($DATA$[{"order":1,"title":"القواعد: مراجعة عامة لما سبقت دراسته","content":"القواعد: مراجعة عامة لما سبقت دراسته\n\nأهداف تعلم قابلة للقياس\n• يميّز أنواع الجملة وأركانها في خمسة أمثلة.\n• يعرب فاعلًا ومفعولًا به وخبرًا وفق مواضعها.\n• يصوّب أخطاء في جمل وظيفية قصيرة.\n\nأفهم الدرس\nنجمع في هذه المراجعة بعض القواعد السابقة من غير أن نعامل الدروس كلها قاعدة واحدة. في «قرأَ العاملُ التنبيهَ» الفاعل العاملُ مرفوع والمفعول التنبيهَ منصوب. وفي «الموعدُ قريبٌ» مبتدأ وخبر مرفوعان. وإذا أدخلنا «كان» قلنا «كان الموعدُ قريبًا»، أما مع «إنَّ» فنقول «إنَّ الموعدَ قريبٌ». ننتبه أيضًا إلى بناء الفعل الماضي وعلامات رفع المثنى والجمع. تفسير الحركة يبدأ بمعرفة وظيفة الكلمة في الجملة، لا بحفظ شكلها منفردًا.\n\nأمثلة وتفسير\n«حضر الموظفانِ» فاعل مثنى مرفوع بالألف. «شكر المديرُ المتطوعينَ» مفعول به جمع مذكر سالم منصوب بالياء. الكلمات نفسها قد تختلف علاماتها عند انتقالها بين الوظائف.\n\nتدريبات تطبيقية\nحدّد الفاعل والمفعول في «سلّم خالدٌ الملفَّ». صحح «كان النشاطَ مفيدٌ». كوّن جملة تبدأ بـ«إنَّ» وبيّن اسمها وخبرها.\n\nمفتاح الإجابة والتغذية الراجعة\nخالدٌ فاعل، الملفَّ مفعول؛ «كان النشاطُ مفيدًا»؛ مثال «إنَّ التعاونَ نافعٌ». يُراجع إعراب كل كلمة قبل التصحيح.\n\nتطبيق في حياتي اليومية\nاقرأ رسالة عمل ثم اختر منها جملة فعلية وأخرى اسمية، وعدّل جملة ثالثة باستخدام كان أو إن دون تغيير مقصد الكاتب.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميّز أنواع الجملة وأركانها في خمسة أمثلة.","يعرب فاعلًا ومفعولًا به وخبرًا وفق مواضعها.","يصوّب أخطاء في جمل وظيفية قصيرة."],"vocabulary":[{"word":"وظيفة إعرابية","meaning":"موقع الكلمة وعملها في تركيب الجملة"},{"word":"علامة فرعية","meaning":"علامة تقوم مقام الحركة الأصلية"}],"quiz":{"prompt":"ما التصحيح المناسب لـ«كان الاجتماعَ مفيدٌ»؟","options":["كان الاجتماعُ مفيدًا","كان الاجتماعَ مفيدًا","كان الاجتماعُ مفيدٌ","إن الاجتماعُ مفيدًا"],"correct":"كان الاجتماعُ مفيدًا"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":2,"title":"القراءة: أنت الهوى - دراسة القصيدة كاملة، والحفظ من 1 إلى 7","content":"القراءة: أنت الهوى - دراسة القصيدة كاملة، والحفظ من 1 إلى 7\n\nأهداف تعلم قابلة للقياس\n• يستخلص معنى المحبة المسؤولة من نص نثري مستقل.\n• يفصل بين المجاز اللغوي والوصف المباشر.\n• يعرف أن حفظ أبيات القصيدة المقررة ينتظر مطابقة مصدرها.\n\nأفهم الدرس\nالعنوان في الخطة «أنت الهوى» مع دراسة القصيدة وحفظ الأبيات 1–7. لا يتوافر لنا في هذا العمل نص الأبيات المثبت من الكتاب، لذلك لا نضع أي أبيات منسوبة للشاعر. نقدم نصًا أصليًا مختلفًا: «يتذكر سالم المواقف التي ساعده فيها أهله وجيرانه. كلما زار حيه القديم رأى المدرسة والساحة، فشعر بالمودة والامتنان. لم يكتف بالحنين، بل ساهم في إصلاح مكتبة صغيرة ليستفيد منها الأطفال والكبار». الحب هنا ليس مجرد إحساس بل سلوك نافع. كلمة «الهوى» في السياق الأدبي قد تدل على الميل والمحبة، ويحدّد معناها الدقيق نصها وسياقها.\n\nأمثلة وتفسير\nالوصف المباشر: شارك في إصلاح المكتبة. الشعور: المودة والامتنان. الاستنتاج: يمكن أن تتحول المحبة إلى خدمة الآخرين دون المبالغة في وصف أعمال لم تحدث.\n\nتدريبات تطبيقية\nاذكر مكانين أثارا ذكريات سالم. استخرج فعلًا يدل على المحبة العملية. اكتب ثلاثة أسطر عن شعور تجاه مكان تحبه دون نسبة كتابتك إلى القصيدة المقررة.\n\nمفتاح الإجابة والتغذية الراجعة\nالمدرسة والساحة؛ ساهم في إصلاح مكتبة؛ تقبل فقرة تميز الشعور والفعل وتراعي الصدق.\n\nتطبيق في حياتي اليومية\nاكتب عملًا بسيطًا يمكنك تقديمه لأسرتك أو مجتمعك تعبيرًا عن التقدير، ثم حدّد كيف تتحقق من أثره.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يستخلص معنى المحبة المسؤولة من نص نثري مستقل.","يفصل بين المجاز اللغوي والوصف المباشر.","يعرف أن حفظ أبيات القصيدة المقررة ينتظر مطابقة مصدرها."],"vocabulary":[{"word":"الهوى","meaning":"الميل أو المحبة بحسب السياق"},{"word":"امتنان","meaning":"شعور بالشكر تجاه المعروف"}],"quiz":{"prompt":"كيف عبّر سالم عن المودة عمليًا؟","options":["ساهم في إصلاح مكتبة","اكتفى بالحنين فقط","تجاهل جيرانه","أغلق المدرسة"],"correct":"ساهم في إصلاح مكتبة"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":3,"title":"القواعد: المقصور والمنقوص والممدود (تثنيتها وجمعها جمعًا سالمًا)","content":"القواعد: المقصور والمنقوص والممدود (تثنيتها وجمعها جمعًا سالمًا)\n\nأهداف تعلم قابلة للقياس\n• يميز بنية الاسم المقصور والمنقوص والممدود.\n• يستنتج التغيير الإملائي عند التثنية.\n• يطبق مثالًا صحيحًا لجمع سالم ويشير إلى شروطه.\n\nأفهم الدرس\nالاسم المقصور آخره ألف لازمة «عصا، فتى»، والمنقوص آخره ياء لازمة مكسور ما قبلها «القاضي»، والممدود آخره همزة قبلها ألف زائدة «صحراء، بناء». في التثنية: عصا ← عصوانِ، فتى ← فتيانِ، القاضي ← القاضيانِ، بناء ← بناءانِ في الاستعمال الذي تبقى فيه الهمزة الأصلية، وصحراء ← صحراوانِ لأن الهمزة فيها للتأنيث. ليست جميع الأسماء قابلة للجمع السالم بلا قيود، وتتأثر الصيغ بأصل الألف ونوع الهمزة والمعنى. يراجع الدارس المعجم عند الشك بدل اختراع جمع لكلمة.\n\nأمثلة وتفسير\n«القاضيانِ» مثنى من القاضي. «صحراوانِ» مثنى من صحراء بسبب همزة التأنيث. «فتيانِ» مثنى من فتى بعد رد الألف إلى أصلها اليائي.\n\nتدريبات تطبيقية\nصنّف «فتى، القاضي، صحراء». اكتب مثنى «عصا» و«فتى». بيّن لماذا لا نكتفي بإضافة «ان» مباشرة إلى «صحراء» في المثال.\n\nمفتاح الإجابة والتغذية الراجعة\nفتى مقصور، القاضي منقوص، صحراء ممدود؛ عصوانِ وفتيانِ؛ همزة التأنيث في صحراء تقلب واوًا عند التثنية.\n\nتطبيق في حياتي اليومية\nإذا ورد اسم من هذه الأنواع في مستند رسمي، تحقق من صيغته عند تثنيته باستخدام مرجع لغوي قبل الإرسال.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميز بنية الاسم المقصور والمنقوص والممدود.","يستنتج التغيير الإملائي عند التثنية.","يطبق مثالًا صحيحًا لجمع سالم ويشير إلى شروطه."],"vocabulary":[{"word":"مقصور","meaning":"اسم معرب آخره ألف لازمة"},{"word":"ممدود","meaning":"اسم معرب آخره همزة قبلها ألف زائدة"}],"quiz":{"prompt":"ما المثنى الصحيح لـ«فتى» في حالة الرفع؟","options":["فتيانِ","فتانِ","فتىانِ","فتوينِ"],"correct":"فتيانِ"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":4,"title":"الإنتاج الكتابي: إعداد خطة عمل للموضوع الإنشائي السردي - تحديد الأحداث الرئيسة","content":"الإنتاج الكتابي: إعداد خطة عمل للموضوع الإنشائي السردي - تحديد الأحداث الرئيسة\n\nأهداف تعلم قابلة للقياس\n• ينظم مخططًا سرديًا من خمس نقاط.\n• يفرق بين الحدث المحوري والتفصيل الهامشي.\n• يربط الأحداث بعبارات زمانية مناسبة.\n\nأفهم الدرس\nقبل كتابة قصة نرسم مسار الأحداث دون تكديس الأوصاف. نفترض موقفًا أصليًا: «خرجت مريم لتجديد بطاقة مكتبة. وصلت قبل الموعد، لكنها نسيت نموذج التسجيل. سألت الموظفة عن طريقة الحصول عليه، وملأته ثم أكملت الإجراء». نكتب الخطة: 1) الشخصية والهدف، 2) المكان والزمن، 3) العقبة، 4) محاولة الحل، 5) النتيجة. التفاصيل مثل لون الباب لا تكون حدثًا رئيسًا إلا إذا أثرت في المشكلة. يساعد المخطط على الحفاظ على منطق السبب والنتيجة.\n\nأمثلة وتفسير\nالأحداث الرئيسة: نسيان النموذج ثم الاستفسار ثم إكمال التسجيل. التفاصيل الثانوية: لون حقيبة مريم، ما لم يترتب عليه شيء.\n\nتدريبات تطبيقية\nرتب «أكملت الطلب، نسيت النموذج، سألت الموظفة، وصلت إلى المكتبة». اكتب مخططًا لزيارة مركز صحي دون اختلاق معلومات طبية أو بيانات أشخاص.\n\nمفتاح الإجابة والتغذية الراجعة\nوصلت، نسيت، سألت، أكملت؛ وتقبل خطة فيها غرض واضح وعقبة وحل ونتيجة.\n\nتطبيق في حياتي اليومية\nاستخدم المخطط عند كتابة تجربة تعلم شخصية، ثم راجع التسلسل مع أحد الزملاء.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["ينظم مخططًا سرديًا من خمس نقاط.","يفرق بين الحدث المحوري والتفصيل الهامشي.","يربط الأحداث بعبارات زمانية مناسبة."],"vocabulary":[{"word":"عقدة","meaning":"حدث يخلق مشكلة تحتاج حلًا"},{"word":"خطة سرد","meaning":"قائمة مرتبة للأحداث قبل الكتابة"}],"quiz":{"prompt":"ما الحدث الذي يمثل العقدة في المثال؟","options":["نسيان نموذج التسجيل","إكمال الطلب","مغادرة المكتبة","كتابة الخاتمة"],"correct":"نسيان نموذج التسجيل"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":5,"title":"القراءة: إلى ولدي","content":"القراءة: إلى ولدي\n\nأهداف تعلم قابلة للقياس\n• يستخلص معنى النصيحة الداعمة من نص أصلي.\n• يميز النصيحة عن الأمر الجارح.\n• يكتب رسالة قصيرة تشجع على التعلم المستمر.\n\nأفهم الدرس\nعنوان الكتاب «إلى ولدي» ولم يُطابق متنه الرسمي في هذا التدقيق. النص التالي أصلي من ضاديوم: «كتب أب لابنه الذي بدأ وظيفة جديدة: يا بني، تعلم من زملائك ولا تخجل من السؤال. إذا أخطأت في عملك فأخبر المسؤول وصحح الخطأ. احفظ وقتك وراع حقوق الآخرين، وتذكّر أن الخبرة تنمو بالممارسة. رد الابن بأنه سيخصص وقتًا أسبوعيًا لتطوير مهاراته». نتعلم أن النصيحة تدعم المسؤولية وتبتعد عن التهديد. وفي أدب الرسائل، تحدد العلاقة بين المرسل والمتلقي درجة القرب واللغة.\n\nأمثلة وتفسير\nعبارة «لا تخجل من السؤال» تشجيع، و«صحح الخطأ» توجيه عملي. لا يستلزم احترام الكبير قبول كل رأي دون تمحيص.\n\nتدريبات تطبيقية\nما ثلاث نصائح في الرسالة؟ كيف يختلف تشجيع الابن عن لومه؟ اكتب أربع جمل إلى متعلم جديد تتضمن تحية وخطوة تعلم محددة.\n\nمفتاح الإجابة والتغذية الراجعة\nطلب التعلم والسؤال وتصحيح الأخطاء واحترام الوقت؛ تقبل رسالة مهذبة ذات مضمون قابل للتطبيق.\n\nتطبيق في حياتي اليومية\nأرسل رسالة دعم إلى شخص يستعد لتعلم مهارة، مستأذنًا قبل مشاركة معلوماته مع غيره.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يستخلص معنى النصيحة الداعمة من نص أصلي.","يميز النصيحة عن الأمر الجارح.","يكتب رسالة قصيرة تشجع على التعلم المستمر."],"vocabulary":[{"word":"نصيحة","meaning":"توجيه يقصد به النفع"},{"word":"ممارسة","meaning":"تكرار منظم لتحسين مهارة"}],"quiz":{"prompt":"ما النصيحة التي تساعد على التعلم في النص؟","options":["لا تخجل من السؤال","أخف الخطأ دائمًا","توقف عن المحاولة","ارفض مساعدة الآخرين"],"correct":"لا تخجل من السؤال"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":6,"title":"القواعد: أسلوب الاستثناء - المستثنى بـ(إلا)","content":"القواعد: أسلوب الاستثناء - المستثنى بـ(إلا)\n\nأهداف تعلم قابلة للقياس\n• يحدد الأداة والمستثنى والمستثنى منه.\n• يعرب المستثنى في التام المثبت.\n• يفرق بين التام المنفي والناقص المنفي.\n\nأفهم الدرس\nفي «حضر المتطوعونَ إلا واحدًا» الأسلوب تام مثبت لأن المستثنى منه «المتطوعون» موجود ولا نفي، و«واحدًا» مستثنى منصوب. وفي «ما حضرَ إلا واحدٌ» الأسلوب ناقص منفي، وتُعرب «واحدٌ» فاعلًا مرفوعًا، لأن الجملة تفرغت لما بعد «إلا». وفي «ما حضر المتطوعون إلا واحدٌ / واحدًا» قد يصح البدل أو النصب في حالات التام المنفي، ولا يصح تعميم حكم واحد على كل السياقات. نحدد وجود النفي والمستثنى منه قبل الإعراب.\n\nأمثلة وتفسير\n«قرأتُ الملفاتَ إلا ملفًا» تام مثبت؛ «ما قرأتُ إلا ملفًا» ناقص منفي والمفعول ملفًا.\n\nتدريبات تطبيقية\nحدد أركان «زارَ الناسُ المعرضَ إلا زائرًا واحدًا» من جهة أداة الاستثناء والمستثنى منه الصحيح في السياق، ثم أعرب «ما جاء إلا سالمٌ». صحح «نجح الطلاب إلا طالبٌ» في الأسلوب التام المثبت.\n\nمفتاح الإجابة والتغذية الراجعة\n«إلا» أداة، لكن جملة «زار الناس المعرض إلا زائرًا» صياغتها متعارضة دلاليًا لأن الزائر من الناس وقد لا يكون من زاره؛ الأفضل «زارَ الطلابُ المعرضَ إلا طالبًا». «سالمٌ» فاعل مرفوع، و«طالبًا» مستثنى منصوب.\n\nتطبيق في حياتي اليومية\nاكتب عن حضور فريق دون ذكر اسم المتغيب الحقيقي إذا لم تكن هناك حاجة.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يحدد الأداة والمستثنى والمستثنى منه.","يعرب المستثنى في التام المثبت.","يفرق بين التام المنفي والناقص المنفي."],"vocabulary":[{"word":"تام","meaning":"أسلوب ذُكر فيه المستثنى منه"},{"word":"مفرّغ","meaning":"استثناء ناقص منفي يعرب ما بعد إلا حسب موقعه"}],"quiz":{"prompt":"ما إعراب «خالدٌ» في «ما جاء إلا خالدٌ»؟","options":["فاعل مرفوع","مستثنى منصوب وجوبًا","مفعول به","خبر كان"],"correct":"فاعل مرفوع"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":7,"title":"القراءة: كن بلسمًا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6","content":"القراءة: كن بلسمًا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6\n\nأهداف تعلم قابلة للقياس\n• يتعرف قيمة التخفيف عن الآخرين في نثر داعم.\n• يستخرج فعلين للتعامل بلطف مع الناس.\n• يميز النثر المساند عن قصيدة الكتاب التي تتطلب توثيقًا مستقلًا.\n\nأفهم الدرس\nترد قصيدة «كن بلسمًا» في الخطة مع دراسة كاملة وحفظ الأبيات 1–6، ولا نعرض أبياتًا لم تُطابق من مصدر الكتاب. نص ضاديوم البديل مستقل: «عاد حسن من عمله ورأى جارًا مسنًا يبحث عن عنوان غرفة في المركز. عرض حسن أن يقرأ له اللوحة، ثم اصطحبه إلى مكتب الاستقبال. شكر الجار مساعدته وقال إنها وفرت عليه وقتًا». نقف عند قيمة الرحمة العملية، ونلاحظ أن المساعدة النافعة تستأذن صاحبها وتراعي سلامته وكرامته، ولا تحوله إلى شخص عاجز في وصفنا.\n\nأمثلة وتفسير\nالمساعدة هنا قراءة اللافتة والإرشاد لا إعطاء وعود لا قدرة على تنفيذها. كلمة «بلسم» في المجاز تشير إلى ما يخفف الألم أو المعاناة.\n\nتدريبات تطبيقية\nما المشكلة التي واجهها الجار؟ كيف ساعده حسن؟ اكتب موقفًا تتعامل فيه بلطف من دون كشف اسم حقيقي، ولا تحفظ الفقرة على أنها القصيدة.\n\nمفتاح الإجابة والتغذية الراجعة\nلم يجد المكان؛ قُرئت له اللوحة وأرشد للمكتب؛ تقبل فقرة قصيرة تظهر أثر السلوك.\n\nتطبيق في حياتي اليومية\nعند مساعدة متعلم آخر، اسأله أولًا عما يحتاجه ثم اعطه فرصة للمحاولة.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يتعرف قيمة التخفيف عن الآخرين في نثر داعم.","يستخرج فعلين للتعامل بلطف مع الناس.","يميز النثر المساند عن قصيدة الكتاب التي تتطلب توثيقًا مستقلًا."],"vocabulary":[{"word":"بلسم","meaning":"مادة أو صورة مجازية لما يخفف المعاناة"},{"word":"رحمة","meaning":"رفق يقود إلى فعل نافع"}],"quiz":{"prompt":"ما الفعل الذي جسّد الرحمة في النص الداعم؟","options":["أرشده إلى مكتب الاستقبال","تركه يبحث وحده","سخر منه","أخفى اللوحة"],"correct":"أرشده إلى مكتب الاستقبال"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":8,"title":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (1)","content":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (1)\n\nأهداف تعلم قابلة للقياس\n• يحدد خمسة عناصر أساسية للقصة.\n• يوظف رابطين زمنيين بين الأحداث.\n• ينشئ بداية وعقدة تمهد لحل معقول.\n\nأفهم الدرس\nتبدأ كتابة القصة بتحديد شخصية ومكان وزمن وهدف وعقبة. في نموذج ضاديوم «دخلت سارة مركز التعلم صباحًا لحضور دورة خط. لم تجد القاعة في الطابق المعتاد، فنظرت إلى لوحة المواعيد الجديدة». هذه بداية وعقدة، ولم نكتب الحل بعد حتى يفكر الدارس في خيار مناسب. يجب أن يرتبط الحل بالمشكلة، فلا نظهر شخصية مفاجئة تنهي كل شيء بلا سبب. روابط «أولًا، بعد ذلك، ثم» توضح الزمن لكنها لا تعوض منطق الأحداث.\n\nأمثلة وتفسير\nالشخصية سارة، المكان مركز التعلم، الهدف دورة الخط، المشكلة تغيّر القاعة. الحل المحتمل الاستفسار من مكتب الاستقبال.\n\nتدريبات تطبيقية\nاكتب مخططًا من خمس نقاط لقصة عن فقدان بطاقة دخول ثم العثور على طريقة رسمية بديلة. ضع سؤالًا ينتظر القارئ جوابه في الوسط.\n\nمفتاح الإجابة والتغذية الراجعة\nتقبل خطة تتضمن الشخصيات والزمان والمكان والعقدة ثم خطوة نحو حل مشروع دون اختراق إجراءات المكان.\n\nتطبيق في حياتي اليومية\nقبل كتابة قصة من الواقع، أخف تفاصيل الأشخاص الآخرين أو استأذنهم.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يحدد خمسة عناصر أساسية للقصة.","يوظف رابطين زمنيين بين الأحداث.","ينشئ بداية وعقدة تمهد لحل معقول."],"vocabulary":[{"word":"عناصر القصة","meaning":"الشخصيات والزمان والمكان والأحداث والعقدة والحل"},{"word":"بداية","meaning":"مدخل يعرف القارئ بالموقف"}],"quiz":{"prompt":"ما العقدة في نموذج سارة؟","options":["لم تجد القاعة في مكانها السابق","حضرت صباحًا","كانت متعلمة","دخلت المركز"],"correct":"لم تجد القاعة في مكانها السابق"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":9,"title":"القواعد: أسلوب الاستثناء - المستثنى بغير وسوى وخلا وعدا","content":"القواعد: أسلوب الاستثناء - المستثنى بغير وسوى وخلا وعدا\n\nأهداف تعلم قابلة للقياس\n• يميّز إعراب غير وسوى وإضافة الاسم بعدهما.\n• يقارن بين خلا وعدا في استعمال فعلي أو حرفي.\n• يكتب أمثلة توضح المستثنى منه.\n\nأفهم الدرس\n«غير» و«سوى» اسمان يستعملان للاستثناء، ويأتي الاسم بعدهما مضافًا إليه مجرورًا: «حضر الجميعُ غيرَ خالدٍ»، فكلمة غير مستثنى منصوب في التام المثبت، وخالد مضاف إليه. «سوى» اسم مقصور تُقدر عليه الحركة المناسبة بحسب الموقع: «حضر الجميعُ سوى خالدٍ». أما «خلا» و«عدا» فقد تستعملان فعلين فينصب ما بعدهما أو حرفي جر فيجر، مثل «حضر الجميعُ خلا خالدًا / خالدٍ» بحسب التخريج. إذا سبقت «ما» المصدرية خلا أو عدا تعيّن النصب في القاعدة المدرسية الشائعة مثل «ما عدا خالدًا».\n\nأمثلة وتفسير\nبعد «غير» و«سوى» الاسم مضاف إليه مجرور. بعد «ما عدا» يأتي الاسم منصوبًا في المثال التعليمي.\n\nتدريبات تطبيقية\nحدد حركة «سالم» في «حضر الجميعُ غيرَ سالمٍ». صحح «ما عدا طالبٍ» بحسب القاعدة التعليمية المقصودة، وحدد أداة الاستثناء في «ما خلا زيدًا».\n\nمفتاح الإجابة والتغذية الراجعة\nسالمٍ مضاف إليه؛ «ما عدا طالبًا»؛ خلا جاءت بعد ما المصدرية في المثال، والاسم منصوب.\n\nتطبيق في حياتي اليومية\nعند كتابة ملاحظة عن حضور مجموعة، اختر أسلوبًا واضحًا وتجنب الالتباس بين الاستثناء والتعميم.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يميّز إعراب غير وسوى وإضافة الاسم بعدهما.","يقارن بين خلا وعدا في استعمال فعلي أو حرفي.","يكتب أمثلة توضح المستثنى منه."],"vocabulary":[{"word":"غير وسوى","meaning":"اسمان للاستثناء مضافان إلى ما بعدهما"},{"word":"خلا وعدا","meaning":"لفظان قد يعربان فعلين أو حرفي جر"}],"quiz":{"prompt":"ما إعراب «عليٍّ» في «حضروا غيرَ عليٍّ»؟","options":["مضاف إليه مجرور","فاعل مرفوع","خبر إن","حال منصوب"],"correct":"مضاف إليه مجرور"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":10,"title":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (2)","content":"الإنتاج الكتابي: كتابة قصة متسلسلة الأحداث مستوفية العناصر (2)\n\nأهداف تعلم قابلة للقياس\n• ينجز حلًا منطقيًا لعقدة قصة سبق التخطيط لها.\n• يربط النتيجة بفعل الشخصية.\n• يراجع القصة كاملة بحثًا عن قفزات زمنية.\n\nأفهم الدرس\nنكمل قصة سارة من الدرس السابق من دون بدء موضوع جديد: «سألت سارة موظفة الاستقبال عن مكان دورة الخط، فأشارت الموظفة إلى إشعار بنقل القاعة. قرأت سارة الرقم الجديد وصعدت إلى الطابق المحدد، ثم وصلت قبل بدء التدريب. سجّلت الرقم في دفترها حتى لا تضيع القاعة في الزيارة المقبلة». جاءت النهاية من حل مرتبط بالمشكلة: سؤال، قراءة الإشعار، الوصول. لا نضيف أحداثًا لا تخدم المعنى، ونسأل بعد المراجعة: هل يعلم القارئ كيف حلّت الشخصية مشكلتها؟\n\nأمثلة وتفسير\nالقصة تبدأ بهدف واضح، وتتقدم بعقبة تغيير القاعة، وتنتهي بخطوات قابلة للفهم. النتيجة ليست حظًا مفاجئًا.\n\nتدريبات تطبيقية\nاكتب نهاية من أربع جمل لقصة فقدان بطاقة الدخول، واجعل الشخصية تتبع الإجراءات الرسمية. راجع ضمائر القصة والوقت والنتيجة.\n\nمفتاح الإجابة والتغذية الراجعة\nتقبل نهاية تُظهر الاستفسار والتحقق واتباع الإجراء ثم الوصول إلى حل دون تجاوز الصلاحيات.\n\nتطبيق في حياتي اليومية\nاستعمل قائمة تحقق عند كتابة قصة للمشاركة أمام زملائك.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["ينجز حلًا منطقيًا لعقدة قصة سبق التخطيط لها.","يربط النتيجة بفعل الشخصية.","يراجع القصة كاملة بحثًا عن قفزات زمنية."],"vocabulary":[{"word":"حل عقدة","meaning":"أحداث تنتهي بها المشكلة"},{"word":"اتساق","meaning":"عدم تناقض أحداث القصة"}],"quiz":{"prompt":"ما الذي جعل نهاية قصة سارة منطقية؟","options":["وجدت إشعار القاعة ثم اتبعته","ظهرت القاعة من دون سبب","تغير الوقت بلا إعلان","لم تسأل أحدًا"],"correct":"وجدت إشعار القاعة ثم اتبعته"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":11,"title":"القراءة: يا شباب العرب","content":"القراءة: يا شباب العرب\n\nأهداف تعلم قابلة للقياس\n• يقرأ فقرة أصلية عن مشاركة الشباب في المجتمع.\n• يفرق بين دعوة عامة وخطوة قابلة للتنفيذ.\n• يقترح تعاونًا يحترم تنوع الخبرات والأعمار.\n\nأفهم الدرس\nالعنوان «يا شباب العرب» في الخطة، لكن هذه الفقرة ليست نص الكتاب. «اجتمع شباب متطوعون مع مجموعة من كبار السن لتنظيم ورشة قراءة رقمية. عرض الشباب طريقة استخدام خدمة عامة عبر الهاتف، وقدم الكبار خبراتهم في التعامل مع الوثائق. تعلّم الجميع أن العطاء لا يرتبط بعمر واحد، وأن نجاح النشاط يتطلب إصغاءً وتبادلًا للأدوار». نلاحظ أن الكلام عن دور الشباب لا ينتقص من قدرة الكبار أو خبراتهم، وأن المهارة تُكتسب بالتعاون.\n\nأمثلة وتفسير\nدعوة عامة: «تعاونوا لخدمة المجتمع». خطوة محددة: «خصصوا ساعة لمساعدة الدارسين على قراءة الإعلانات العامة».\n\nتدريبات تطبيقية\nما الخبرة التي قدمها كبار السن؟ ماذا قدم الشباب؟ اكتب اقتراحًا لنشاط من ثلاث خطوات يشترك فيه أشخاص من جيلين.\n\nمفتاح الإجابة والتغذية الراجعة\nخبرات التعامل مع الوثائق؛ شرح خدمة عبر الهاتف؛ تقبل اقتراحًا يوزع المهام ويحترم المشاركين.\n\nتطبيق في حياتي اليومية\nاقترح نشاطًا تعليميًا صغيرًا يجمع تعلم مهارة رقمية وخبرة عملية من الحياة اليومية.\n\nالتوثيق: هذا شرح أصلي مستقل من ضاديوم يدعم عنوانًا مثبتًا في خطة التعليم المستمر للفصل الأول البحريني 2026–2027. ليس نقلًا حرفيًا من كتاب الوزارة ولا إثباتًا لاكتمال فهرس الكتاب. لم تتم مطابقة نصوص الأشعار الرسمية، ويحتاج هذا المحتوى إلى مراجعة تربوية تحريرية قبل اعتماد الدرس.\nSOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","learning_objectives":["يقرأ فقرة أصلية عن مشاركة الشباب في المجتمع.","يفرق بين دعوة عامة وخطوة قابلة للتنفيذ.","يقترح تعاونًا يحترم تنوع الخبرات والأعمار."],"vocabulary":[{"word":"تطوع","meaning":"مشاركة نافعة برضا الشخص"},{"word":"تبادل خبرات","meaning":"مشاركة المعرفة بين أشخاص مختلفين"}],"quiz":{"prompt":"ما الذي ساعد على نجاح الورشة في النص؟","options":["تبادل خبرات الشباب والكبار","الاعتماد على عمر واحد","منع الأسئلة","إلغاء التعاون"],"correct":"تبادل خبرات الشباب والكبار"},"origin":"DADYOOM_BH_REINFORCEMENT2_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$DATA$::jsonb))
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT l.id,'تدريب ضاديوم للتحقق من الفهم','multiple_choice',
 'اختر الإجابة الوحيدة الصحيحة. نشاط أصلي داعم يحتاج مراجعة تربوية.',
 jsonb_build_object('origin','DADYOOM_BH_REINFORCEMENT2_MCQ_V1','selection_mode','single','options',i.j->'quiz'->'options','editorial_review','required','book_text_copied',false),
 1,5,true,'assessment',i.j->'quiz'->>'prompt',jsonb_build_object('correct',i.j->'quiz'->>'correct'),false
FROM items i
JOIN public.lessons l ON l.title=i.j->>'title' AND l.sort_order=(i.j->>'order')::int AND l.content LIKE '%SOURCE=DADYOOM_BH_REINFORCEMENT2_DRAFT_V1%'
JOIN public.units u ON u.id=l.unit_id AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الثاني تقوية' AND g.grade_number IS NULL
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.content->>'origin'='DADYOOM_BH_REINFORCEMENT2_MCQ_V1');